CREATE TRIGGER grant_assignment_entries_delete AFTER DELETE ON access_grant_entries BEGIN
  UPDATE entries SET mutation_revision=mutation_revision+1 WHERE owner_id=(SELECT owner_id FROM access_grants WHERE grant_id=OLD.grant_id);
END

CREATE TRIGGER grant_assignment_entries_insert AFTER INSERT ON access_grant_entries BEGIN
  UPDATE entries SET mutation_revision=mutation_revision+1 WHERE owner_id=(SELECT owner_id FROM access_grants WHERE grant_id=NEW.grant_id);
END

CREATE TRIGGER grant_assignment_insert AFTER INSERT ON access_grants BEGIN
  UPDATE entries SET mutation_revision=mutation_revision+1 WHERE owner_id=NEW.owner_id;
END

CREATE TRIGGER grant_assignment_update AFTER UPDATE ON access_grants BEGIN
  UPDATE entries SET mutation_revision=mutation_revision+1 WHERE owner_id=NEW.owner_id;
END

CREATE TRIGGER sources_pause_rules_on_revoke AFTER UPDATE OF revoked_at ON sources WHEN OLD.revoked_at IS NULL AND NEW.revoked_at IS NOT NULL BEGIN
  UPDATE service_routes SET paused_at=COALESCE(paused_at,NEW.revoked_at) WHERE owner_id=NEW.owner_id AND source_id=NEW.source_id AND entry_id IS NOT NULL;
  DELETE FROM unassigned_context WHERE owner_id=NEW.owner_id AND source_id=NEW.source_id;
END

CREATE TRIGGER sources_pause_rules_on_unrevoke AFTER UPDATE OF revoked_at ON sources WHEN OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS NULL BEGIN
  UPDATE service_routes SET paused_at=COALESCE(paused_at,OLD.revoked_at) WHERE owner_id=NEW.owner_id AND source_id=NEW.source_id AND entry_id IS NOT NULL;
  DELETE FROM unassigned_context WHERE owner_id=NEW.owner_id AND source_id=NEW.source_id;
END
